We solve \eqref{eq:fast} or \eqref{eq:avr}
by a classical time-splitting spectral scheme as follows \cite{BJM, HJMSZ}:

\textbf{Step 1.} We solve the equation
\begin{equation}
\label{ts1}
\begin{aligned}
&\, \mathrm{i} \partial _t u_1 = -\, \Delta u_1, \\
\end{aligned}
\end{equation}
on a fixed time interval $\Delta t$, relying on the
\emph{pseudo-spectral} method.
Thus we can get the value of $u_1$ at new time
$t^{n+1}$ by
\[u^{n+1}_1=\(e^{-\mathrm{i}\Delta t |\xi|^2}\hat{u}_1^{n}(\xi)\)^\vee,\]
here `$\wedge$' and `$\vee$' denote the Fourier and inverse Fourier
transform respectively.

Let $\rho(t^{n+1},\boldsymbol{\rm{x}})=|u_1(t^{n+1},\boldsymbol{\rm{x}})|^2$, then we compute the Hartree potential $V_{Hartree}$ by
\[V_{Hartree}(t^{n+1},\boldsymbol{\rm{x}})=\(\frac{1}{|\xi|^2}\hat{\rho}(t^{n+1}, \xi)\)^\vee.\]

\textbf{Step 2.} We solve the ordinary differential equation
\begin{equation}
\label{ts2}
\begin{aligned}
& \,\mathrm{i} \partial _tu_2  = \left(C_1V_{Hartree}+V(t,\boldsymbol{\rm{x}})-a|u_2|^\sigma\right)u_2, \quad u_2(t^{n},\boldsymbol{\rm{x}})=u_1(t^{n+1},\boldsymbol{\rm{x}}),
\end{aligned}
\end{equation}
on the same time-interval, here $V(t,\boldsymbol{\rm{x}})$ is given by \eqref{eq:fast-p} or \eqref{eq:avr-p}.
It is easy to check that in this step the density $\rho(t,\boldsymbol{\rm{x}})\equiv|u_2|^2(t,\boldsymbol{\rm{x}})$ and consequently the Hartree potential do not change in time, hence
\[ u_2(t+\Delta t,\boldsymbol{\rm{x}})=u_2(t,\boldsymbol{\rm{x}})\,\exp\({\displaystyle-\mathrm{i} \int_{t}^{t+\Delta t}
\left(C_1V_{Hartree}(\boldsymbol{\rm{x}})+V(s,\boldsymbol{\rm{x}})-a\rho^\frac{\sigma}{2}(\boldsymbol{\rm{x}})\right) ds}\)
\] with $\rho(\boldsymbol{\rm{x}})=|u_1(t^{n+1},\boldsymbol{\rm{x}})|^2$, $V_{Hartree}(x)=\(\frac{1}{|\xi|^2}\hat{\rho}(\xi)\)^\vee$.

The key is to calculate the oscillatory integral,
\begin{equation}\int_{t}^{t+\Delta t} \frac{1}{\left|\boldsymbol{\rm{x}}-b(s)\right|}ds\equiv \int_{t}^{t+\Delta t} \frac{1}{\left|\boldsymbol{\rm{x}}-e(s)\sin(2\pi\omega s)\right|}ds,\label{2.3}\end{equation}
where $|\omega|\gg1$, particularly due to the occurrence of the singularity in the kernel.
Therefore, we use a regularization technique. For example, we could take
\begin{equation}\int_{t}^{t+\Delta t} \frac{1}{\left|\boldsymbol{\rm{x}}-b(s)\right|}ds\approx \int_{t}^{t+\Delta t}\Phi^\eta \(\frac{1}{\left|\boldsymbol{\rm{x}}-b(s)\right|}\)ds,\label{2.4}\end{equation}
where
\[\Phi^\eta \(\frac{1}{\left|\boldsymbol{\rm{x}}-b(s)\right|}\)=\(\frac{2}{\eta}\)^{\frac{3}{2}}
\int_{\mathbb{R}^3}e^{-2\pi\frac{|\boldsymbol{\rm{x}}-\boldsymbol{\rm{x}}'|^2}{\eta}}\frac{1}{\left|\boldsymbol{\rm{x}}'-b(s)\right|}d\boldsymbol{\rm{x}}'.\]


In Section \ref{anal:sect} we will discuss the stability with respect to perturbations of the potential.

The energies for two models are
\begin{equation}\label{eq:energy1}
E^\omega(t):=\int_{\mathbb{R}^3}\(|\nabla u^\omega|^2+\frac{C_1}{2}|\nabla V_{Hartree}^\omega|^2
+cV^\omega|u^\omega|^2-a\frac{2}{\sigma+2}|u^\omega|^{\sigma+2}\)d\boldsymbol{\rm{x}},
\end{equation}
and
\begin{equation}\label{eq:energy2}
E(t):=\int_{\mathbb{R}^3}\(|\nabla u|^2+\frac{C_1}{2}|\nabla V_{Hartree}|^2+{c}\langle V\rangle|u|^2-a\frac{2}{\sigma+2}|u|^{\sigma+2}\)d\boldsymbol{\rm{x}},
\end{equation}
respectively. The total mass
\begin{equation}\label{eq:mass}
M(t):=\int_{\mathbb{R}^3}|u(t,\boldsymbol{\rm{x}})|^2d\boldsymbol{\rm{x}},
\end{equation}
is conserved in both models.

